Set-Location -LiteralPath $PSScriptRoot
$msg = 'import: a real CRM export could not be imported, and the reason was reported as a network failure. Restland Dynamics export carries Full Name and Phone E164 and no Last Name column at all. HEADER_MAP knew neither spelling, so _build_column_lookup found no last_name and the importer raised before reading a single row of a legitimate 100-lead file. The Phone E164 half was the more dangerous one: it mapped to nothing, so every phone number in the file would have been dropped even once the name was fixed. Adds a full_name alias set consulted ONLY when no explicit last-name column exists, E.164 and other real phone spellings, and split_full_name which strips honorifics and generational suffixes so the last token is genuinely the family name - Dr. Daniel Pham is Pham and John Smith Jr. is Smith, not Jr. That matters more here than in most systems because the name is what a funeral home says out loud to a grieving family, and dedup keys on the last name, so a suffix landing there both misaddresses people and silently corrupts duplicate matching. Second bug, and the reason the first was so hard to see: the ValueError was uncaught, so it became a bare 500 raised ABOVE the CORS middleware and reached the browser with no Access-Control-Allow-Origin header. The browser refused the response, fetch rejected, and the frontend honest reading of a rejected fetch is Unable to reach the server - so a wrong column name and a dead backend produced the identical message and people went looking at their wifi. Both import endpoints now return 400 with the actual reason, and an app-level exception handler returns a real JSONResponse so any future crash stays inside the middleware stack and arrives as a 500 the page can read, with the traceback still logged in full and only the client-facing body generic. Third: the API client retried every failed request three times including FormData uploads, so a transport failure after /leads/upload/confirm had already committed would import the whole batch again, and a consumed File stream made the replay fail for a different reason than the original. Uploads are no longer retried and their failure says nothing was imported.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
